INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5805519, 846174, 98775, '<td valign="top">I like the clearly defined sculpting of the snow by the wind and the shadows cast by the sun. This picture has nice flow.  A wide angle lens converging the sides might have swept the clouds up a little, too, adding some movement from the top down to the windmill with the snow doing the same from the bottom, IMHO.</td>', 'I like the clearly defined sculpting of the snow by the wind and the shadows cast by the sun. This picture has nice flow.  A wide angle lens converging the sides might have swept the clouds up a little, too, adding some movement from the top down to the windmill with the snow doing the same from the bottom, IMHO.', '2010-01-11 00:15:56.000000', NULL, 1),
(5805527, 845670, 98775, '<td valign="top">is this acid, or just some noise added? I love the feel and the tone, but you added so much that the rust and the clouds are pixelated. It gives the whole picture a neglected feel instead of just the plough. Still this picture stands out from the crowd.</td>', 'is this acid, or just some noise added? I love the feel and the tone, but you added so much that the rust and the clouds are pixelated. It gives the whole picture a neglected feel instead of just the plough. Still this picture stands out from the crowd.', '2010-01-11 00:19:41.000000', NULL, 1),
(5805537, 845393, 96574, '<td valign="top">Ouch! LOL</td>', 'Ouch! LOL', '2010-01-11 00:24:01.000000', NULL, 1),
(5805543, 846301, 98775, '<td valign="top">this has a very cool feel to it.</td>', 'this has a very cool feel to it.', '2010-01-11 00:28:40.000000', NULL, 1),
(5805566, 846230, 83313, '<td valign="top">Needs more Topaz. (OK, just kidding!) Nice old crusty car.</td>', 'Needs more Topaz. (OK, just kidding!) Nice old crusty car.', '2010-01-11 00:54:44.000000', NULL, 1),
(5805570, 846304, 83313, '<td valign="top">I would say since this worked nicely as a challenge entry, that it does indeed still work, and therefore does not meet the challenge topic. :-}</td>', 'I would say since this worked nicely as a challenge entry, that it does indeed still work, and therefore does not meet the challenge topic. :-}', '2010-01-11 00:57:02.000000', NULL, 1),
(5805572, 846279, 83313, '<td valign="top">Just a basic plain shot that illustrates the item, I''m afraid. You could have done some interesting things with angles and the lighting on this.</td>', 'Just a basic plain shot that illustrates the item, I''m afraid. You could have done some interesting things with angles and the lighting on this.', '2010-01-11 00:58:35.000000', NULL, 1),
