INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5810612, 845686, 46918, '<td valign="top">The pic is a little washed out... It really looks more like a painting than a pic. Don''t get me wrong it is a great photo......I''ll give you a 7</td>', 'The pic is a little washed out... It really looks more like a painting than a pic. Don''t get me wrong it is a great photo......I''ll give you a 7', '2010-01-13 19:36:23.000000', NULL, 1),
(5810628, 846126, 76598, '<td valign="top">Color blind here, but it strikes me as being too yellow</td>', 'Color blind here, but it strikes me as being too yellow', '2010-01-13 19:42:19.000000', NULL, 1),
(5810648, 845213, 76598, '<td valign="top">I have one of those myself, it was a great camera</td>', 'I have one of those myself, it was a great camera', '2010-01-13 19:49:10.000000', NULL, 1),
(5810725, 846105, 46918, '<td valign="top">This works well as a b&amp;w..</td>', 'This works well as a b&w..', '2010-01-13 20:38:04.000000', NULL, 1),
(5810728, 846138, 46918, '<td valign="top">I just don''t like the colors depicted in this pic...</td>', 'I just don''t like the colors depicted in this pic...', '2010-01-13 20:40:26.000000', NULL, 1),
(5810735, 846106, 46918, '<td valign="top">good lighting...good subject. good job.</td>', 'good lighting...good subject. good job.', '2010-01-13 20:42:53.000000', NULL, 1),
(5810744, 846294, 46918, '<td valign="top">Good antique feel. good lighting, nice composure.</td>', 'Good antique feel. good lighting, nice composure.', '2010-01-13 20:46:02.000000', NULL, 1),
(5810745, 845393, 105441, '<td valign="top">Great and humorous take on the challenge.  Lighting is too harsh, though.  And I think the guy is watching Letterman...</td>', 'Great and humorous take on the challenge.  Lighting is too harsh, though.  And I think the guy is watching Letterman...', '2010-01-13 20:46:28.000000', NULL, 1),
(5810750, 846301, 46918, '<td valign="top">Kindof blurry...I would have liked a sharper focus...</td>', 'Kindof blurry...I would have liked a sharper focus...', '2010-01-13 20:47:14.000000', NULL, 1),
(5810759, 846294, 105441, '<td valign="top">I think the original image wasn''t really worthy of the effort put in to make it special.  The vignetting effect (why is the top not included in the effect?) feels unnatural, and the focus is lacking.  The framing would be better if the pier remains started in the lower left, then tailed off diagonally toward the upper right.</td>', 'I think the original image wasn''t really worthy of the effort put in to make it special.  The vignetting effect (why is the top not included in the effect?) feels unnatural, and the focus is lacking.  The framing would be better if the pier remains started in the lower left, then tailed off diagonally toward the upper right.', '2010-01-13 20:53:11.000000', NULL, 1),
(5810762, 845873, 105441, '<td valign="top">Technically excellent, but it does feel like a catalog photo rather than art which reduces the overall score for me.</td>', 'Technically excellent, but it does feel like a catalog photo rather than art which reduces the overall score for me.', '2010-01-13 20:54:44.000000', NULL, 1),
(5810767, 845686, 105441, '<td valign="top">The locomotive portion of the image is cool, but the depth of field also allows the distractions of the houses to detract.  The post processing is probably a little heavy as well, though I suspect that you were going for that look.</td>', 'The locomotive portion of the image is cool, but the depth of field also allows the distractions of the houses to detract.  The post processing is probably a little heavy as well, though I suspect that you were going for that look.', '2010-01-13 20:57:45.000000', NULL, 1),
(5810769, 846201, 105441, '<td valign="top">Weird but effective - a 7 for me.</td>', 'Weird but effective - a 7 for me.', '2010-01-13 20:59:19.000000', NULL, 1),
(5810773, 846258, 105441, '<td valign="top">I like this.  The diagonals work, and the decay is effectively conveyed.</td>', 'I like this.  The diagonals work, and the decay is effectively conveyed.', '2010-01-13 21:02:15.000000', NULL, 1),
(5810780, 846123, 105441, '<td valign="top">Nice juxtaposition, and well executed.  Lighting is soft, diagonal is good, blur of the in-line skate is right - 8!</td>', 'Nice juxtaposition, and well executed.  Lighting is soft, diagonal is good, blur of the in-line skate is right - 8!', '2010-01-13 21:10:08.000000', NULL, 1),
(5810782, 846174, 105441, '<td valign="top">Nice image, I like the B&amp;W treatment, but the horizon should be level in my judgement.  A 7 though.</td>', 'Nice image, I like the B&W treatment, but the horizon should be level in my judgement.  A 7 though.', '2010-01-13 21:12:06.000000', NULL, 1),
(5810786, 846173, 105441, '<td valign="top">I like the look, but close inspection seems to show some artifacts from processing.  You might consider placing the boat to the right, to give it space to ''move forward'' in the image.</td>', 'I like the look, but close inspection seems to show some artifacts from processing.  You might consider placing the boat to the right, to give it space to ''move forward'' in the image.', '2010-01-13 21:16:54.000000', NULL, 1),
(5810790, 846291, 105441, '<td valign="top">A perspective that hid the rooftops would help.  I like the colors and the horizontal stripes.</td>', 'A perspective that hid the rooftops would help.  I like the colors and the horizontal stripes.', '2010-01-13 21:18:47.000000', NULL, 1),
(5810796, 846178, 105441, '<td valign="top">Nicely done, colors are great.</td>', 'Nicely done, colors are great.', '2010-01-13 21:23:06.000000', NULL, 1),
(5810801, 846316, 105441, '<td valign="top">Nice processing, not overdone.  Clear, subtle colors. My favorite so far.</td>', 'Nice processing, not overdone.  Clear, subtle colors. My favorite so far.', '2010-01-13 21:23:58.000000', NULL, 1),
(5810803, 846275, 105441, '<td valign="top">Nice nod to recognize the passing this week, and well executed.  Good light.</td>', 'Nice nod to recognize the passing this week, and well executed.  Good light.', '2010-01-13 21:24:58.000000', NULL, 1),
(5810806, 846296, 105441, '<td valign="top">The light is a bit dull...</td>', 'The light is a bit dull...', '2010-01-13 21:26:02.000000', NULL, 1),
(5810807, 846065, 46918, '<td valign="top">I don''t like the focus.....</td>', 'I don''t like the focus.....', '2010-01-13 21:26:57.000000', NULL, 1),
(5810810, 845670, 46918, '<td valign="top">Good shot..I like the rustic feel. Great colors. I give it a 6.</td>', 'Good shot..I like the rustic feel. Great colors. I give it a 6.', '2010-01-13 21:28:34.000000', NULL, 1),
(5810813, 846268, 90495, '<td valign="top">Wish the background were blurrier &lt;--- wow that''s a word!</td>', 'Wish the background were blurrier <--- wow that''s a word!', '2010-01-13 21:29:38.000000', NULL, 1),
(5810814, 846053, 105441, '<td valign="top">I''d like to see the original image side by side with this.  The processing distorts the perspective too much for me, but it is an interesting effect.</td>', 'I''d like to see the original image side by side with this.  The processing distorts the perspective too much for me, but it is an interesting effect.', '2010-01-13 21:30:16.000000', NULL, 1),
