(5810818, 844642, 105441, '<td valign="top">Great execution, interesting subject, good lines.  An 8.</td>', 'Great execution, interesting subject, good lines.  An 8.', '2010-01-13 21:31:40.000000', NULL, 1),
(5810822, 846036, 90495, '<td valign="top">Background could have been less busy. Love the subject matter.</td>', 'Background could have been less busy. Love the subject matter.', '2010-01-13 21:33:00.000000', NULL, 1),
