(5810825, 845806, 105441, '<td valign="top">Great choice of subject, but I would think there is a more interesting angle or perspective (as opposed to eye-high, straight on).</td>', 'Great choice of subject, but I would think there is a more interesting angle or perspective (as opposed to eye-high, straight on).', '2010-01-13 21:34:02.000000', NULL, 1),
(5810828, 846099, 105441, '<td valign="top">The curves of the paper and the light patterns are superb.</td>', 'The curves of the paper and the light patterns are superb.', '2010-01-13 21:34:41.000000', NULL, 1),
