INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5816292, 846318, 83313, '<td valign="top">Nice job on this one, General. It gave me an idea for a no-pressure side challenge.</td>', 'Nice job on this one, General. It gave me an idea for a no-pressure side challenge.', '2010-01-18 00:38:30.000000', NULL, 0),
(5816301, 846268, 73056, '<td valign="top">Give me a break! The clarity and processing on this is a 10+. These people need new eyeglasses. Only a few people on this site can achieve such pure, clear, beautiful images and you are one of them. Sorry, had to vent when I saw this challenge and your score. Way underrated.<br/><br/><i>Message edited by author 2010-01-18 03:43:37.</i></td>', 'Give me a break! The clarity and processing on this is a 10+. These people need new eyeglasses. Only a few people on this site can achieve such pure, clear, beautiful images and you are one of them. Sorry, had to vent when I saw this challenge and your score. Way underrated.', '2010-01-18 00:44:42.000000', '2010-01-18 03:43:37.000000', 0),
(5816307, 846033, 83313, '<td valign="top">A darn good first effort. I gave it a 7, for what you did accomplish with it. I see you had the same problem I did with my first real effort, that the tank walls attracted bubbles and droplets. I had to reshoot mine, and the second time around I wiped off the glass every 3 or 4 drops. It gave me a much cleaner background and foreground. I also think the next time I will find some non-reflective, waterproof surface to place inside the back of the tank, so that I don''t have to deal with reflections off the back of the tank glass.</td>', 'A darn good first effort. I gave it a 7, for what you did accomplish with it. I see you had the same problem I did with my first real effort, that the tank walls attracted bubbles and droplets. I had to reshoot mine, and the second time around I wiped off the glass every 3 or 4 drops. It gave me a much cleaner background and foreground. I also think the next time I will find some non-reflective, waterproof surface to place inside the back of the tank, so that I don''t have to deal with reflections off the back of the tank glass.', '2010-01-18 00:46:30.000000', NULL, 0),
(5816310, 846296, 83313, '<td valign="top">Maybe it needed more Topaz?</td>', 'Maybe it needed more Topaz?', '2010-01-18 00:48:24.000000', NULL, 0),
(5816312, 846065, 83313, '<td valign="top">I''m surprised at the number of good entries that came in with a mediocre average on this challenge. I gave this a 7 and expected it to place at least mid-pack. You can never really know how the broad appeal will fall.</td>', 'I''m surprised at the number of good entries that came in with a mediocre average on this challenge. I gave this a 7 and expected it to place at least mid-pack. You can never really know how the broad appeal will fall.', '2010-01-18 00:51:42.000000', NULL, 0),
(5816314, 846275, 83313, '<td valign="top">You got robbed. I love Gumby. I was trying to leave an in-challenge comment, but nothing appropriate came to mind.</td>', 'You got robbed. I love Gumby. I was trying to leave an in-challenge comment, but nothing appropriate came to mind.', '2010-01-18 00:55:32.000000', NULL, 0),
(5816316, 845693, 47933, '<td valign="top">Well look at you in the top 10. This is wonderful as is ALL of your work.</td>', 'Well look at you in the top 10. This is wonderful as is ALL of your work.', '2010-01-18 01:00:03.000000', NULL, 0),
(5816317, 845576, 83313, '<td valign="top">Well, I''m at least glad to see I could leave you a comment giving you some clue to why it bombed. I hate when I get low voted with no explanation of why.</td>', 'Well, I''m at least glad to see I could leave you a comment giving you some clue to why it bombed. I hate when I get low voted with no explanation of why.', '2010-01-18 01:01:43.000000', NULL, 0),
